-- Only program metadata is public. Provider provenance remains in the private catalog.
create or replace function public.program_resources_v43(p_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if coalesce(cardinality(p_ids),0)<1 or cardinality(p_ids)>50 then raise exception 'Select 1 to 50 programs';end if;
 return (select coalesce(jsonb_agg(jsonb_build_object(
  'program_id',program_id,'name',name,'kind',case when source='Residency Explorer' then 'interview_rates' else 'program_details' end,
  'source_cycle',source_cycle,'source_date',source_date,'fields',fields,
  'website_url',website_url,'website_scope',website_scope,'website_verified_at',website_verified_at) order by source desc,name),'[]')
 from cme_private.program_source_catalog_v43 where program_id=any(p_ids));
end $$;
revoke all on function public.program_resources_v43(uuid[]) from public;
grant execute on function public.program_resources_v43(uuid[]) to anon,authenticated;
create or replace function public.program_source_directory_v43(p_query text default '',p_offset integer default 0)
returns jsonb language sql stable security definer set search_path='' as $$
 with candidates as (
  select p.id,p.name,p.city,p.state,p.acgme_program_id from public.programs p
  where exists(select 1 from cme_private.program_source_catalog_v43 c where c.program_id=p.id and
   (coalesce(p_query,'')='' or concat_ws(' ',p.name,p.city,p.state,p.acgme_program_id,c.name,c.city,c.state) ilike '%'||left(p_query,160)||'%'))
  order by p.name,p.id limit 31 offset greatest(0,least(coalesce(p_offset,0),5000))
 ), page as (select * from candidates order by name,id limit 30)
 select jsonb_build_object('programs',coalesce((select jsonb_agg(jsonb_build_object(
  'program_id',id,'acgme_program_id',acgme_program_id,'name',name,'city',city,'state',state,
  'resources',public.program_resources_v43(array[id])) order by name,id) from page),'[]'),
  'has_more',(select count(*)>30 from candidates));
$$;
revoke all on function public.program_source_directory_v43(text,integer) from public;
grant execute on function public.program_source_directory_v43(text,integer) to anon,authenticated;
-- This catalog deliberately remains private and read only through bounded metadata RPCs.
alter table cme_private.program_source_catalog_v43 enable row level security;
revoke all on cme_private.program_source_catalog_v43 from public,anon,authenticated;
